actions.script:
def vehicle = ec.entity.find("zenith.erp.fleet.Vehicle").condition("vehicleId", vehicleId).one()
if (!vehicle) { ec.message.addError("Vehicle not found"); return }

def activeAssignment = ec.entity.find("zenith.erp.fleet.VehicleAssignment")
    .condition("vehicleId", vehicleId).condition("statusId", "VaAssigned").list()
if (activeAssignment) { ec.message.addError("Vehicle is already assigned to a driver"); return }

context.assignmentId = ec.entity.sequencedIdPrimary("zenith.erp.fleet.VehicleAssignment", null, null)
def odometer = odometerAtAssignment ?: vehicle.currentOdometerKm ?: 0
ec.entity.makeValue("zenith.erp.fleet.VehicleAssignment").setAll([
    assignmentId: context.assignmentId, vehicleId: vehicleId, driverId: driverId,
    assignedDate: ec.user.nowTimestamp, odometerAtAssignment: odometer,
    purpose: purpose, statusId: "VaAssigned"
]).create()

vehicle.set("assignedDriverPartyId", driverId)
vehicle.update()

def assignment = ec.entity.find("zenith.erp.fleet.VehicleAssignment")
    .condition("assignmentId", assignmentId).one()
if (!assignment) { ec.message.addError("Assignment not found"); return }

assignment.set("statusId", "VaReturned")
assignment.set("returnDate", ec.user.nowTimestamp)
if (odometerAtReturn) assignment.set("odometerAtReturn", odometerAtReturn)
assignment.update()

def vehicle = ec.entity.find("zenith.erp.fleet.Vehicle")
    .condition("vehicleId", assignment.vehicleId).one()
if (vehicle) {
    vehicle.set("assignedDriverPartyId", null)
    if (odometerAtReturn) vehicle.set("currentOdometerKm", odometerAtReturn)
    vehicle.update()
}

def totalAmount = (quantityLitres ?: 0) * (ratePerLitre ?: 0)
context.fuelLogId = ec.entity.sequencedIdPrimary("zenith.erp.fleet.FuelLog", null, null)
ec.entity.makeValue("zenith.erp.fleet.FuelLog").setAll([
    fuelLogId: context.fuelLogId, vehicleId: vehicleId, driverId: driverId,
    fuelDate: fuelDate ?: ec.user.nowTimestamp, fuelType: fuelType,
    quantityLitres: quantityLitres, ratePerLitre: ratePerLitre,
    totalAmount: totalAmount, odometerKm: odometerKm,
    fuelStationName: fuelStationName, fuelStationCity: fuelStationCity,
    receiptNumber: receiptNumber, paymentMode: paymentMode, isFullTank: isFullTank
]).create()

if (odometerKm) {
    def vehicle = ec.entity.find("zenith.erp.fleet.Vehicle").condition("vehicleId", vehicleId).one()
    if (vehicle && (!vehicle.currentOdometerKm || odometerKm > vehicle.currentOdometerKm)) {
        vehicle.set("currentOdometerKm", odometerKm)
        vehicle.update()
    }
}

import java.time.LocalDate
def now = LocalDate.now()
def fysSetting = ec.entity.find("zenith.erp.base.CompanySettings").condition("organizationPartyId", ec.user.getPreference("ACTIVE_ORGANIZATION")).condition("settingKey", "FY_START_MONTH").one()
int fyStartMonth = fysSetting ? (fysSetting.settingValue as int) : 4
int fyStart = now.monthValue >= fyStartMonth ? now.year : now.year - 1
String fySuffix = String.format("%02d-%02d", fyStart % 100, (fyStart + 1) % 100)

def lastTrip = ec.entity.find("zenith.erp.fleet.TripLog")
    .condition("tripNumber", "like", "TRIP/${fySuffix}/%").orderBy("-tripNumber").limit(1).list()
int nextSeq = 1
if (lastTrip) {
    def parts = lastTrip[0].tripNumber.split("/")
    if (parts.length == 3) nextSeq = (parts[2] as int) + 1
}
String tripNumber = "TRIP/${fySuffix}/" + String.format("%05d", nextSeq)

context.tripId = ec.entity.sequencedIdPrimary("zenith.erp.fleet.TripLog", null, null)
ec.entity.makeValue("zenith.erp.fleet.TripLog").setAll([
    tripId: context.tripId, tripNumber: tripNumber, vehicleId: vehicleId,
    driverId: driverId, fromLocation: fromLocation, toLocation: toLocation,
    purpose: purpose, statusId: "TrPlanned",
    plannedStartDate: plannedStartDate ?: ec.user.nowTimestamp
]).create()

def trip = ec.entity.find("zenith.erp.fleet.TripLog").condition("tripId", tripId).one()
if (!trip) { ec.message.addError("Trip not found"); return }
if (trip.statusId != "TrPlanned") { ec.message.addError("Trip must be in Planned status"); return }
trip.set("statusId", "TrInProgress")
trip.set("actualStartDate", ec.user.nowTimestamp)
if (startOdometerKm) trip.set("startOdometerKm", startOdometerKm)
trip.update()

def trip = ec.entity.find("zenith.erp.fleet.TripLog").condition("tripId", tripId).one()
if (!trip) { ec.message.addError("Trip not found"); return }
if (trip.statusId != "TrInProgress") { ec.message.addError("Trip must be In Progress"); return }

trip.set("statusId", "TrCompleted")
trip.set("actualEndDate", ec.user.nowTimestamp)
if (endOdometerKm) {
    trip.set("endOdometerKm", endOdometerKm)
    if (trip.startOdometerKm)
        trip.set("distanceKm", endOdometerKm - (trip.startOdometerKm as BigDecimal))
}
if (tollAmount) trip.set("tollAmount", tollAmount)
if (otherExpenses) trip.set("otherExpenses", otherExpenses)
if (remarks) trip.set("remarks", remarks)
trip.update()

if (endOdometerKm && trip.vehicleId) {
    def vehicle = ec.entity.find("zenith.erp.fleet.Vehicle").condition("vehicleId", trip.vehicleId).one()
    if (vehicle && (!vehicle.currentOdometerKm || endOdometerKm > (vehicle.currentOdometerKm as BigDecimal))) {
        vehicle.set("currentOdometerKm", endOdometerKm)
        vehicle.update()
    }
}

def svc = ec.entity.find("zenith.erp.fleet.VehicleService").condition("serviceId", serviceId).one()
if (!svc) { ec.message.addError("Service record not found"); return }

svc.set("statusId", "VsCompleted")
if (laborCost) svc.set("laborCost", laborCost)
if (partsCost) svc.set("partsCost", partsCost)
svc.set("totalCost", ((laborCost ?: svc.laborCost ?: 0) as BigDecimal) + ((partsCost ?: svc.partsCost ?: 0) as BigDecimal))
if (nextServiceDate) svc.set("nextServiceDate", nextServiceDate)
if (nextServiceOdometerKm) svc.set("nextServiceOdometerKm", nextServiceOdometerKm)
svc.update()

def vehicle = ec.entity.find("zenith.erp.fleet.Vehicle").condition("vehicleId", svc.vehicleId).one()
if (vehicle && vehicle.statusId == "VhInMaintenance") {
    vehicle.set("statusId", "VhActive")
    vehicle.update()
}

def finder = ec.entity.find("zenith.erp.fleet.FuelLog").condition("vehicleId", vehicleId)
if (fromDate) finder.condition("fuelDate", ">=", fromDate)
if (toDate) finder.condition("fuelDate", "<=", toDate)
def logs = finder.orderBy("odometerKm").list()

if (logs.size() < 2) {
    context.totalKm = 0; context.totalLitres = 0; context.kmPerLitre = 0; return
}
def firstOdo = logs[0].odometerKm as BigDecimal
def lastOdo = logs[-1].odometerKm as BigDecimal
context.totalKm = lastOdo - firstOdo

BigDecimal litres = 0
for (int i = 1; i < logs.size(); i++) litres += (logs[i].quantityLitres ?: 0) as BigDecimal
context.totalLitres = litres
context.kmPerLitre = litres > 0 ? (context.totalKm / litres).setScale(2, java.math.RoundingMode.HALF_UP) : 0
